-- 只读；必须显式选择本次评审的专属随机 schema。输出定义与计数，不读取正文。
SELECT DATABASE() AS selected_schema,VERSION() AS mysql_version,@@innodb_page_size AS page_size;
SELECT table_name,engine,table_rows,data_length,index_length FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN ('agent_memory_execution','agent_memory_invalidation_receipt','agent_context_operation','agent_context_manifest','agent_memory_context_refresh');
SELECT table_name,ordinal_position,column_name,column_type,is_nullable,column_default,character_set_name,collation_name,extra,generation_expression FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name IN ('agent_memory_execution','agent_memory_invalidation_receipt','agent_context_operation','agent_context_manifest','agent_memory_context_refresh') ORDER BY table_name,ordinal_position;
SELECT table_name,index_name,seq_in_index,column_name,non_unique,sub_part FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name IN ('agent_memory_execution','agent_memory_invalidation_receipt','agent_context_operation','agent_context_manifest','agent_memory_context_refresh') ORDER BY table_name,index_name,seq_in_index;
SELECT c.table_name,c.constraint_name,c.constraint_type,k.check_clause FROM information_schema.table_constraints c LEFT JOIN information_schema.check_constraints k ON k.constraint_schema=c.constraint_schema AND k.constraint_name=c.constraint_name WHERE c.table_schema=DATABASE() AND c.table_name IN ('agent_memory_execution','agent_memory_invalidation_receipt','agent_context_operation','agent_context_manifest','agent_memory_context_refresh') ORDER BY c.table_name,c.constraint_name;
SELECT table_name,column_name,referenced_table_name,referenced_column_name,ordinal_position FROM information_schema.key_column_usage WHERE table_schema=DATABASE() AND table_name IN ('agent_memory_execution','agent_memory_invalidation_receipt','agent_context_operation','agent_context_manifest','agent_memory_context_refresh') AND referenced_table_name IS NOT NULL ORDER BY table_name,constraint_name,ordinal_position;
SELECT trigger_name,event_object_table,action_timing,event_manipulation,action_order,action_statement FROM information_schema.triggers WHERE trigger_schema=DATABASE() AND event_object_table IN ('agent_memory_execution','agent_memory_context_refresh') ORDER BY event_object_table,action_order,trigger_name;
SELECT COUNT(*) AS existing_delta_columns FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='agent_memory_execution' AND column_name='current_context_fingerprint';
SELECT COUNT(*) AS incompatible_execution_bodies FROM agent_memory_execution WHERE (state='SCRUBBED' AND (snapshot_ciphertext IS NOT NULL OR snapshot_nonce IS NOT NULL OR scrub_event_id IS NULL OR scrub_authority IS NULL)) OR (state IN ('ACTIVE','REVOKED') AND (snapshot_ciphertext IS NULL OR snapshot_nonce IS NULL OR scrub_event_id IS NOT NULL OR scrub_authority IS NOT NULL)) OR state NOT IN ('ACTIVE','REVOKED','SCRUBBED');
SELECT state,COUNT(*) AS row_count FROM agent_memory_execution GROUP BY state;
SELECT trx_id,trx_state,trx_started,trx_rows_locked FROM information_schema.innodb_trx;
